import sys


def gcd(a, b):
    while b:
        a, b = b, a % b
    return a


def lcm(a, b):
    return a * b // gcd(a, b)


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        nums = [int(x) for x in line.split()]
        if not nums:
            continue
        gcd_val = abs(nums[0])
        lcm_val = abs(nums[0])
        for n in nums[1:]:
            gcd_val = gcd(gcd_val, abs(n))
            lcm_val = lcm(lcm_val, abs(n))
        print(gcd_val, lcm_val)


if __name__ == "__main__":
    main()
